/** Create NetSuiteServiceClient */
export function createClientAsync(...args: Parameters<typeof soapCreateClientAsync>): Promise<NetSuiteServiceClient> {
    return soapCreateClientAsync(args[0], args[1], args[2]) as any;
}

/** add a Account record. */
export async function addAccount(client: NetSuiteServiceClient, tokenPassport: TokenPassport, body: Account) {
    const [res] = await client.addAsync({ record: body }, { headers: { tokenPassport } });
    return res;
}

/** get a Account record. */
export async function getAccount(client: NetSuiteServiceClient, tokenPassport: TokenPassport, body: RecordRef) {
    const [res] = await client.getAsync({ baseRef: body }, { headers: { tokenPassport } });
    return res;
}

