export async function getWorkOrder(client: NetSuiteServiceClient, tokenPassport: TokenPassport, body: RecordRef) {
    const [res] = await client.getAsync({ baseRef: body }, { headers: { tokenPassport } });
    return res;
}

/** search a WorkOrder record. */
export async function searchWorkOrder(client: NetSuiteServiceClient, tokenPassport: TokenPassport, body: WorkOrderSearchBasic) {
    const [res] = await client.searchAsync({ searchRecord: body }, { headers: { tokenPassport } });
    return res;
}

